.od-theme-shadcn .od-button--tab{border:0;border-bottom:2px solid transparent;border-radius:0;background:transparent;box-shadow:none}
.od-theme-shadcn .od-button--tab[aria-selected="true"]{border-bottom-color:var(--foreground)}
@media(prefers-reduced-motion:reduce){.od-theme-shadcn .od-button{transition:none}}
.od-shared-card{display:flex;flex-direction:column;min-width:0;background:var(--od-paper);border:1px solid var(--od-line);border-radius:var(--radius-surface);color:var(--od-ink);box-shadow:0 1px 2px #0000000b}
.od-shared-card-content{padding:var(--space-3)}
.od-shared-card[data-size="sm"] .od-shared-card-content{padding:var(--space-2)}

@scope(.send-queue-app){:scope{box-sizing:border-box;width:100%;min-width:0;margin:0;padding:12px;color:var(--od-sub);font-size:13px;line-height:1.6;overflow-wrap:anywhere}p{margin:0}p+p{margin-top:8px}.send-queue-guide-title{color:var(--od-ink);font-weight:600}}
